<section class="panel section-gap"><div class="panel-heading"><div><h2>Enrollment receipts</h2><p>Deposits and installments record income as received. Open Payments to collect the remaining balance and view payment history.</p></div></div><div class="table-wrap"><table><thead><tr><th>Student / fee</th><th>Due date</th><th>Fee / FOC</th><th>Paid</th><th>Balance</th><th>Invoice</th></tr></thead><tbody><?php foreach($invoices as $i): ?><tr><td><strong><?= e($i['name']??$student['name']) ?></strong><small><?= e($i['description']) ?></small></td><td><?= e($i['due_date']) ?></td><td><?= $i['is_foc']?'FOC':money($i['amount']) ?></td><td><?= money($i['paid']) ?></td><td><?= money((float)$i['amount']-(float)$i['paid']) ?></td><td><a class="text-link" href="<?= e(url('invoices/'.$i['id'].'/print')) ?>" target="_blank" rel="noopener">Print A4</a> <a class="button small" href="<?= e(url('invoices/'.$i['id'].'/payments')) ?>">Payments</a></td></tr><?php endforeach ?><?php if(!$invoices): ?><tr><td colspan="6" class="empty">No fees recorded.</td></tr><?php endif ?></tbody></table></div></section>
